<?php
namespace App\Modules\Orders\Presentation\Http\Controllers;
use App\Http\Controllers\Controller;use App\Modules\Identity\Domain\Models\AuthorizationRequest;use App\Modules\Orders\Domain\Enums\SalesOrderStatus;use App\Modules\Orders\Domain\Models\SalesOrder;use Illuminate\Http\Request;use Inertia\Inertia;use Inertia\Response;
class EditSalesOrderController extends Controller {public function __invoke(Request $request,SalesOrder $order,CreateSalesOrderController $create):Response{abort_unless($request->user()->hasPermission('orders.manage')&&$order->status===SalesOrderStatus::Draft,403);$order->load(['lines','customer.customerProfile']);$auth=AuthorizationRequest::query()->where('resource_type',$order->getMorphClass())->where('resource_id',$order->id)->where('approval_permission','prices.authorize-below-minimum')->get()->filter->isUsable()->first();return Inertia::render('orders/Edit',$create->props()+['order'=>[...$order->only(['id','price_list_id','discount','notes']),'customer_profile_id'=>$order->customer->customerProfile->id,'ordered_at'=>$order->ordered_at->format('Y-m-d\TH:i'),'due_at'=>$order->due_at->format('Y-m-d\TH:i'),'priority'=>$order->priority->value,'price_authorization_id'=>$auth?->id,'lines'=>$order->lines->map(fn($l)=>['presentation_id'=>$l->presentation_id,'quantity'=>$l->ordered_quantity,'unit_price'=>$l->unit_price,'discount'=>$l->discount,'price_reason'=>$l->price_reason,'notes'=>$l->notes])]]);}}
